00230     public static function stopAllServicesParallel($bearsamppBins, ?callable $progressCallback = null, $shutdownTimeout = 15)
00231     {
00232         Log::trace('ServiceHelper::stopAllServicesParallel() starting');
00233         $startTime = microtime(true);
00234 
00235         $services = $bearsamppBins->getServices();
00236         if (empty($services)) {
00237             Log::trace('No services to shut down');
00238             return true;
00239         }
00240 
00241         Log::trace('Starting parallel shutdown of ' . count($services) . ' services');
00242 
00243         // Try parallel shutdown
00244         $parallelSuccess = self::shutdownServicesParallel($services, $progressCallback, $shutdownTimeout);
00245 
00246         if ($parallelSuccess) {
00247             $duration = round(microtime(true) - $startTime, 3);
00248             Log::info('Parallel shutdown completed successfully in ' . $duration . 's');
00249             return true;
00250         }
00251 
00252         // Fallback to sequential
00253         Log::info('Parallel shutdown timed out, falling back to sequential shutdown');
00254         $sequentialSuccess = self::shutdownServicesSequential($services, $progressCallback);
00255 
00256         $totalDuration = round(microtime(true) - $startTime, 3);
00257         Log::info('Sequential shutdown completed in ' . $totalDuration . 's');
00258 
00259         return $sequentialSuccess;
00260     }
