00274     private static function shutdownServicesParallel($services, ?callable $progressCallback = null, $shutdownTimeout = 15)
00275     {
00276         Log::trace('Phase 1: Sending stop commands to all services');
00277         $totalServices = count($services);
00278         $currentIndex = 0;
00279 
00280         // Phase 1: Send stop commands (non-blocking)
00281         foreach ($services as $serviceName => $service) {
00282             $currentIndex++;
00283             if ($progressCallback) {
00284                 $progressCallback($currentIndex, $totalServices, $serviceName);
00285             }
00286 
00287             Log::trace('Sending stop to: ' . $serviceName);
00288             $service->stop();
00289         }
00290 
00291         // Phase 2: Monitor status
00292         Log::trace('Phase 2: Monitoring service status');
00293         $monitorStartTime = microtime(true);
00294         $monitorTimeout = $shutdownTimeout;
00295         $checkInterval = 0.5;
00296         $allStopped = false;
00297 
00298         while ((microtime(true) - $monitorStartTime) < $monitorTimeout) {
00299             $allStopped = true;
00300 
00301             foreach ($services as $serviceName => $service) {
00302                 if (!$service->isStopped()) {
00303                     $allStopped = false;
00304                     break;
00305                 }
00306             }
00307 
00308             if ($allStopped) {
00309                 Log::trace('All services stopped in parallel phase');
00310                 return true;
00311             }
00312 
00313             usleep($checkInterval * 1000000);
00314         }
00315 
00316         // Phase 3: Force kill remaining services
00317         Log::trace('Phase 3: Force killing remaining services');
00318         foreach ($services as $serviceName => $service) {
00319             if (!$service->isStopped()) {
00320                 Log::trace('Force killing: ' . $serviceName);
00321                 self::forceKillService($serviceName);
00322             }
00323         }
00324 
00325         // Final check
00326         return self::allServicesStopped($services);
00327     }
00328 
