00369     private static function forceKillService($serviceName)
00370     {
00371         $processMap = [
00372             BinApache::SERVICE_NAME => 'httpd.exe',
00373             BinMysql::SERVICE_NAME => 'mysqld.exe',
00374             BinMariadb::SERVICE_NAME => 'mysqld.exe',
00375             BinMailpit::SERVICE_NAME => 'mailpit.exe',
00376             BinMemcached::SERVICE_NAME => 'memcached.exe',
00377             BinPostgresql::SERVICE_NAME => 'postgres.exe',
00378             BinXlight::SERVICE_NAME => 'xlightftpd.exe',
00379             'nodejs' => 'node.exe',  // NodeJS - not a Windows service but needs to be killed on exit
00380         ];
00381 
00382         if (isset($processMap[$serviceName])) {
00383             Log::trace('Killing process: ' . $processMap[$serviceName]);
00384             Win32Ps::killBins([$processMap[$serviceName]]);
00385             return true;
00386         }
00387 
00388         return false;
00389     }
