00463     private static function startServicesParallel($serviceInfos, ?callable $progressCallback = null, $startupTimeout = 30)
00464     {
00465         Log::trace('Phase 1: Sending start commands to all services');
00466         $totalServices = count($serviceInfos);
00467         $currentIndex = 0;
00468 
00469         // Phase 1: Send start commands (non-blocking)
00470         foreach ($serviceInfos as $serviceName => $serviceInfo) {
00471             $currentIndex++;
00472             if ($progressCallback) {
00473                 $progressCallback($currentIndex, $totalServices, $serviceInfo['name']);
00474             }
00475 
00476             Log::trace('Sending start to: ' . $serviceName);
00477             $service = $serviceInfo['service'];
00478 
00479             // Start the service
00480             $service->start();
00481         }
00482 
00483         // Phase 2: Monitor status
00484         Log::trace('Phase 2: Monitoring service status');
00485         $monitorStartTime = microtime(true);
00486         $monitorTimeout = $startupTimeout;
00487         $checkInterval = 0.5;
00488         $allRunning = false;
00489         $failedServices = [];
00490 
00491         while ((microtime(true) - $monitorStartTime) < $monitorTimeout) {
00492             $allRunning = true;
00493 
00494             foreach ($serviceInfos as $serviceName => $serviceInfo) {
00495                 $service = $serviceInfo['service'];
00496 
00497                 if (!$service->isRunning()) {
00498                     $allRunning = false;
00499                     $failedServices[$serviceName] = $serviceInfo;
00500                 }
00501             }
00502 
00503             if ($allRunning) {
00504                 Log::trace('All services running in parallel phase');
00505                 return true;
00506             }
00507 
00508             usleep($checkInterval * 1000000);
00509         }
00510 
00511         // Phase 3: Retry failed services
00512         if (!empty($failedServices)) {
00513             Log::trace('Phase 3: Retrying ' . count($failedServices) . ' failed services');
00514 
00515             foreach ($failedServices as $serviceName => $serviceInfo) {
00516                 $service = $serviceInfo['service'];
00517 
00518                 if (!$service->isRunning()) {
00519                     Log::trace('Retrying start for: ' . $serviceName);
00520                     $service->start();
00521                     usleep(500000); // 500ms delay between retries
00522                 }
00523             }
00524 
00525             // Final check
00526             return self::allServicesRunning($serviceInfos);
00527         }
00528 
00529         return true;
00530     }
00531 
00542     private static function startServicesSequential($serviceInfos, ?callable $progressCallback = null)
00543     {
00544         Log::trace('Starting sequential startup phase');
00545         $totalServices = count($serviceInfos);
00546         $currentIndex = 0;
00547 
00548         foreach ($serviceInfos as $serviceName => $serviceInfo) {
00549             $currentIndex++;
00550             if ($progressCallback) {
00551                 $progressCallback($currentIndex, $totalServices, $serviceInfo['name']);
00552             }
00553 
00554             Log::trace('Sequential start: ' . $serviceName);
00555             $service = $serviceInfo['service'];
00556 
00557             $service->start();
00558 
00559             // Small delay between service starts
00560             usleep(200000);
00561 
00562             if (!$service->isRunning()) {
00563                 Log::trace('Service failed to start: ' . $serviceName);
00564                 // Retry once
00565                 $service->start();
00566                 usleep(500000);
00567             }
00568         }
00569 
00570         return self::allServicesRunning($serviceInfos);
00571     }
00572 
00579     private static function allServicesRunning($serviceInfos)
00580     {
00581         foreach ($serviceInfos as $serviceName => $serviceInfo) {
00582             $service = $serviceInfo['service'];
00583             if (!$service->isRunning()) {
00584                 return false;
00585             }
00586         }
00587         return true;
